// Active-play world clock: one complete day every twelve minutes.
function clockTime(){return (15+(s.worldSeconds||0)*24/720)%24}
function worldDaylight(){return Math.max(0,Math.min(1,(Math.sin((clockTime()-6)*Math.PI/12)+.12)/1.12))}
const clockHUD=document.createElement('div');clockHUD.className='world-clock';gameScene.append(clockHUD);
function clockDisplay(){let t=clockTime(),h=Math.floor(t),m=Math.floor(t%1*60);clockHUD.textContent=(worldDaylight()>.3?'DAY ':'NIGHT ')+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')}
const residentNames={station:['The porter','“The last train always has two empty seats. Read the ticket on the desk before you board.”'],library:['The archivist','“You may erase a name, or keep the records. The register is inside.”'],cinema:['The projectionist','“Switch on the projector and watch the kitchen. The note describes a moment that has not happened yet.”'],clinic:['The night nurse','“The case file is waiting. You don’t have to sign anything you don’t understand.”'],chapel:['The candle keeper','“Some people come for their names. Some stay to keep a light burning.”'],radio:['The engineer','“The microphone works both ways. Read the emergency transcript before you answer.”']};
function residents(){return cityWorld().filter(c=>residentNames[c.id]).map((c,i)=>({id:c.id,name:residentNames[c.id][0],x:c.x+6,z:c.z+1.5+Math.sin((s.worldSeconds||0)*.35+i)*1.1,coat:['#756b59','#4e6970','#775857','#668071','#827754','#66647d'][i],phase:i}))}
function speakResident(id){let p=residentNames[id];modal(p[0],p[1]+(worldDaylight()<.15?'\n\nFor a moment, they look past you. “There’s someone standing where your shadow should be.”':''),[['Ask about this place',()=>cityVenue(id)],['Goodbye',close]])}
const livingTargets=targets;targets=function(){let all=livingTargets().concat(residents().map(p=>({name:'Talk to '+p.name,p:[p.x,1.45,p.z],fn:()=>speakResident(p.id)})));let c=cityWorld().find(c=>c.id==='cinema');all.push({name:'Cinema projector',p:[c.x-1.5,1,c.z+1],fn:projectorControls});return all};
const livingSurface=surface;surface=function(t){if(t.name.startsWith('Talk to '))return quadAt([t.p[0],.9,t.p[2]-.03],.52,1.7,'z');if(t.name==='Cinema projector')return quadAt(t.p,.55,.6,'z');return livingSurface(t)};
function residentVertices(){let data=[];function limb(x,y,z,w,h,d,c){let v=[[x-w/2,y,z-d/2],[x+w/2,y,z-d/2],[x+w/2,y+h,z-d/2],[x-w/2,y+h,z-d/2],[x-w/2,y,z+d/2],[x+w/2,y,z+d/2],[x+w/2,y+h,z+d/2],[x-w/2,y+h,z+d/2]],rgb=c.match(/\w\w/g).map(n=>parseInt(n,16)/255);for(let f of [[0,1,2,3],[5,4,7,6],[4,0,3,7],[1,5,6,2],[3,2,6,7]])for(let j of [0,1,2,0,2,3])data.push(...v[f[j]],...rgb)}for(let p of residents()){if(Math.hypot(p.x-house.x,p.z-house.z)>30)continue;let stride=Math.sin((s.worldSeconds||0)*1.4+p.phase)*.08;limb(p.x-.11,.06,p.z+stride,.14,.65,.2,'#303e3c');limb(p.x+.11,.06,p.z-stride,.14,.65,.2,'#303e3c');limb(p.x,.67,p.z,.46,.67,.27,p.coat);limb(p.x-.29,.72,p.z,.11,.56,.14,p.coat);limb(p.x+.29,.72,p.z,.11,.56,.14,p.coat);limb(p.x,1.38,p.z,.24,.3,.23,'#b29b80');limb(p.x,1.64,p.z,.26,.07,.25,'#4c4739');limb(p.x-.06,1.55,p.z+.12,.025,.025,.02,'#252b22');limb(p.x+.06,1.55,p.z+.12,.025,.025,.02,'#252b22')}return new Float32Array(data)}
function drawResidents(){if(!gpu)return;const gl=gpu.gl;gpu.peopleBuffer??=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,gpu.peopleBuffer);let data=residentVertices();gl.bufferData(gl.ARRAY_BUFFER,data,gl.DYNAMIC_DRAW);gl.vertexAttribPointer(gpu.position,3,gl.FLOAT,false,24,0);gl.vertexAttribPointer(gpu.color,3,gl.FLOAT,false,24,12);gl.drawArrays(gl.TRIANGLES,0,data.length/6);gl.bindBuffer(gl.ARRAY_BUFFER,gpu.buffer);gl.vertexAttribPointer(gpu.position,3,gl.FLOAT,false,24,0);gl.vertexAttribPointer(gpu.color,3,gl.FLOAT,false,24,12)}
function projectorControls(){modal('The cinema projector','The note says: “The projector plays your kitchen. On screen, Mother is about to open the spare room.”\n\nWatch the screen inside the cinema to see it happen.',[[s.projectorOn?'Switch off':'Switch on and watch',()=>{s.projectorOn=!s.projectorOn;if(s.projectorOn)s.projectorTime=0;save();close();say(s.projectorOn?'The projector starts. Face the large screen at the back of the cinema.':'The projector winds down.')}],['Keep exploring',close]])}
const filmCanvas=document.createElement('canvas');filmCanvas.width=640;filmCanvas.height=360;const filmCtx=filmCanvas.getContext('2d');
function projectorFrame(time){let g=filmCtx,t=time%14,opening=Math.max(0,Math.min(1,(t-6)/4));g.fillStyle='#313b30';g.fillRect(0,0,640,360);g.fillStyle='#655e48';g.fillRect(0,260,640,100);g.fillStyle='#aaa18a';g.fillRect(20,65,145,120);g.fillStyle='#576e69';g.fillRect(28,73,129,104);g.fillStyle='#b2aa92';g.fillRect(90,73,6,104);g.fillRect(28,120,129,6);g.fillStyle='#66573e';g.fillRect(20,215,230,55);g.fillStyle='#a49a80';g.fillRect(15,207,240,10);g.fillStyle='#191f17';g.fillRect(418,70,139,219);g.fillStyle='#67553a';g.beginPath();g.moveTo(418,70);g.lineTo(557-opening*115,70+opening*26);g.lineTo(557-opening*115,289-opening*20);g.lineTo(418,289);g.closePath();g.fill();g.fillStyle='#d1bd7d';g.fillRect(540-opening*112,184,6,7);
let x=280+Math.min(1,t/6)*119;g.fillStyle='#535b48';g.fillRect(x-17,182,34,72);g.fillStyle='#c2af92';g.beginPath();g.arc(x,165,15,0,Math.PI*2);g.fill();g.fillStyle='#939685';g.fillRect(x-16,147,32,12);g.fillStyle='#434e3d';g.fillRect(x+14,192,Math.max(8,50*Math.min(1,t/6)),10);if(opening>.5){g.fillStyle='#0a130d';g.fillRect(465,160,25,90);g.beginPath();g.arc(478,147,13,0,Math.PI*2);g.fill()}g.fillStyle='#e3dfc5';g.font='18px Georgia';g.textAlign='center';g.fillText(t<6?'MOTHER WALKS TOWARDS THE DOOR':t<10?'SHE OPENS THE SPARE ROOM':'SOMEONE INSIDE HAS YOUR FACE',320,335);g.strokeStyle='#171e1460';for(let y=0;y<360;y+=4){g.beginPath();g.moveTo(0,y);g.lineTo(640,y);g.stroke()}return filmCanvas}
const filmDecals=drawDecals;drawDecals=function(){filmDecals();let c=cityWorld().find(c=>c.id==='cinema');if(s.projectorOn&&Math.abs(house.x-c.x)<5&&house.z>c.z-5.7&&house.z<c.z+4.2){let q=quadAt([c.x,1.8,c.z-5.72],6,1.6,'z');q=[q[1],q[0],q[3],q[2]];drawFilm(projectorFrame(s.projectorTime||0),q)}};
function drawFilm(img,world){let v=world.map(view);if(v.some(p=>p[2]<.12))return;let p=v.map(screen),src=[[0,360],[640,360],[640,0],[0,0]];for(let i of [1,2])texturedTriangle(img,[src[0],src[i],src[i+1]],[p[0],p[i],p[i+1]])}
const projectorBuild=buildHouse;buildHouse=function(){projectorBuild();let c=cityWorld().find(c=>c.id==='cinema');table(c.x-1.5,c.z+1,.7,.6);box(c.x-1.5,.82,c.z+1,.45,.35,.38,'#56645b');cylinder(c.x-1.5,1.17,c.z+1,.15,.06,'#788777');box(c.x,1.7,c.z-5.74,6.2,.04,.035,'#242c25');};
const lifeMovement=updateMovement;let visualClock=-1;updateMovement=function(dt){lifeMovement(dt);if(s.ending||s.sanityLost)return;s.worldSeconds=(s.worldSeconds||0)+dt;let c=cityWorld().find(c=>c.id==='cinema');if(s.projectorOn&&Math.abs(house.x-c.x)<5&&house.z>c.z-6&&house.z<c.z+4){s.projectorTime=(s.projectorTime||0)+dt;let screenView=view([c.x,1.8,c.z-5.72]);if(screenView[2]>.1&&Math.abs(screenView[0]/screenView[2])<.7&&Math.abs(screenView[1]/screenView[2])<.6)s.projectorWatched=(s.projectorWatched||0)+dt;if(s.projectorWatched>10&&!s.projectorSeen){s.projectorSeen=true;save();say('On the screen, Mother opens the spare room. Someone with your face is waiting inside.');drainSanity(4)}}let frame=Math.floor(s.worldSeconds*12);if(frame!==visualClock){visualClock=frame;house.dirty=true;clockDisplay()}};
const lifeTasks=taskRows;taskRows=function(){return lifeTasks().concat([{label:'Cinema: watch Mother open the spare room',done:!!s.projectorSeen}])};
const lifeReset=reset;reset=function(){lifeReset();s.worldSeconds=0;s.projectorOn=false;s.projectorTime=0;s.projectorSeen=false;s.projectorWatched=0;save();clockDisplay()};
const peopleCollision=canWalk;canWalk=function(x,z){if(!peopleCollision(x,z))return false;return !residents().some(p=>Math.hypot(x-p.x,z-p.z)<.42)};
clockDisplay();render();
